BEGIN
  SELECT id INTO v_dept_id FROM departments WHERE name = 'Técnicos de Enfermagem' AND active = true LIMIT 1;
  IF v_dept_id IS NULL THEN
    RAISE EXCEPTION 'Setor Técnicos de Enfermagem não encontrado.';
  END IF;

  SELECT id INTO v_admin_id
  FROM system_users
  WHERE role_id = (SELECT id FROM user_roles WHERE name = 'Administrador' LIMIT 1)
  AND active = true
  ORDER BY created_at LIMIT 1;

  SELECT id INTO v_schedule_id
  FROM monthly_schedules
  WHERE department_id = v_dept_id AND month = '2026-06-01' LIMIT 1;

  IF v_schedule_id IS NULL THEN
    INSERT INTO monthly_schedules (department_id, month, name, status, created_by)
    VALUES (v_dept_id, '2026-06-01', 'Escala Técnicos de Enfermagem - Junho de 2026', 'Rascunho', v_admin_id)
    RETURNING id INTO v_schedule_id;
    RAISE NOTICE 'Escala criada: %', v_schedule_id;
