      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 3, 'SD', 'Serviço Diurno (7h às 19h) 12h', '07:00', '19:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 5, 'SD', 'Serviço Diurno (7h às 19h) 12h', '07:00', '19:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 8, 'SN', 'Serviço Noturno (19h às 7h) 12h', '19:00', '07:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 10, 'SN', 'Serviço Noturno (19h às 7h) 12h', '19:00', '07:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 11, 'M', 'Manhã (7h às 13h) 6h', '07:00', '13:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 13, 'SD', 'Serviço Diurno (7h às 19h) 12h', '07:00', '19:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 15, 'SN', 'Serviço Noturno (19h às 7h) 12h', '19:00', '07:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 18, 'SD', 'Serviço Diurno (7h às 19h) 12h', '07:00', '19:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 20, 'SN', 'Serviço Noturno (19h às 7h) 12h', '19:00', '07:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 23, 'SN', 'Serviço Noturno (19h às 7h) 12h', '19:00', '07:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 25, 'SN', 'Serviço Noturno (19h às 7h) 12h', '19:00', '07:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 28, 'SD', 'Serviço Diurno (7h às 19h) 12h', '07:00', '19:00'),
      ('TAINA BARBARA DE JESUS TRIGUEIROS AS', 'taina', 'as', 30, 'SN', 'Serviço Noturno (19h às 7h) 12h', '19:00', '07:00')
    ) AS t(sheet_name, first_word, last_word, day, code, type_name, start_time, end_time)
  ) LOOP
    SELECT id INTO v_prof_id
    FROM professionals
    WHERE active = true
      AND department_id = v_dept_id
      AND unaccent(lower(split_part(full_name, ' ', 1))) = rec.first_word
      AND unaccent(lower(reverse(split_part(reverse(full_name), ' ', 1)))) = rec.last_word
    LIMIT 1;

    IF v_prof_id IS NULL THEN
      SELECT id INTO v_prof_id
      FROM professionals
      WHERE active = true
        AND department_id = v_dept_id
        AND unaccent(lower(regexp_replace(full_name, '\.', '', 'g'))) = unaccent(lower(rec.sheet_name))
      LIMIT 1;
    END IF;

    IF v_prof_id IS NULL THEN
      RAISE NOTICE 'NÃO ENCONTRADO no setor Técnicos de Enfermagem: %', rec.sheet_name;
      skipped_count := skipped_count + 1;
      CONTINUE;
    END IF;

    BEGIN
      INSERT INTO shifts (
        professional_id, department_id, schedule_id,
        shift_date, shift_type, start_time, end_time,
        status, created_by
      ) VALUES (
        v_prof_id, v_dept_id, v_schedule_id,
        ('2026-06-' || lpad(rec.day::text, 2, '0'))::date,
        rec.type_name, rec.start_time::time, rec.end_time::time,
        'Agendado', v_admin_id
      );
      inserted_count := inserted_count + 1;
    EXCEPTION WHEN unique_violation THEN
      NULL;
    END;
    matched_count := matched_count + 1;
  END LOOP;

  RAISE NOTICE '------------------------------------------';
  RAISE NOTICE 'Setor: Técnicos de Enfermagem';
  RAISE NOTICE 'Turnos processados (match): %', matched_count;
  RAISE NOTICE 'Turnos inseridos: %', inserted_count;
  RAISE NOTICE 'Turnos pulados (sem match): %', skipped_count;
  RAISE NOTICE '------------------------------------------';
END $$;

SELECT
  p.full_name,
  COUNT(s.id) as total_turnos
FROM monthly_schedules ms
JOIN shifts s ON s.schedule_id = ms.id
JOIN professionals p ON p.id = s.professional_id
WHERE ms.month = '2026-06-01'
  AND ms.department_id = (SELECT id FROM departments WHERE name = 'Técnicos de Enfermagem')
GROUP BY p.full_name
ORDER BY p.full_name;
